//! ↩️ reorder-accessors leaf-owned inverse reconstruction from exact base values.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfAccessor;
use crate::artifacts::gltf::schema::mutations::reorder_accessors::mutation::{validate, GltfReorderAccessorsPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{accessors_op, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.reorder-accessors.v1.inverse";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfReorderAccessorsInverseOperation { Insert { position: usize, item: GltfAccessor }, Delete { index: usize, removed: GltfAccessor }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfReorderAccessorsInverse { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfReorderAccessorsPayload, pub operation: GltfReorderAccessorsInverseOperation }
fn operation(payload: &GltfReorderAccessorsPayload, base: &GltfSnapshot) -> GltfReorderAccessorsInverseOperation { GltfReorderAccessorsInverseOperation::Reorder { order: (0..payload.order.len()).map(|index| payload.order.iter().position(|value| *value == index).unwrap()).collect() } }
fn touched_paths(payload: &GltfReorderAccessorsPayload) -> Vec<String> { payload.order.iter().map(|index| format!("document/accessors/{}", index)).chain(std::iter::empty()).collect() }
pub fn validate_inverse(inverse: &GltfReorderAccessorsInverse) -> Result<(), GltfTopLevelMutationRejection> { if inverse.id != ID || inverse.version != 1 { return Err(reject("gltf.mutation.invalid-inverse-envelope", "inverse", "descriptor identity does not match")); } if inverse.touched_paths != touched_paths(&inverse.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "inverse/touchedPaths", "paths must be concrete payload-derived locations")); } Ok(()) }
pub fn apply_inverse(inverse: &GltfReorderAccessorsInverse, after: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_inverse(inverse)?; let operation = &inverse.operation; match operation { GltfReorderAccessorsInverseOperation::Insert { position, .. } if *position > after.document.accessors.len() => return Err(reject("gltf.mutation.insert-out-of-range", "document/accessors", "position must be within the collection")), GltfReorderAccessorsInverseOperation::Delete { index, .. } if *index >= after.document.accessors.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/accessors", "index must address an item")), GltfReorderAccessorsInverseOperation::Move { index, position } if *index >= after.document.accessors.len() || *position >= after.document.accessors.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/accessors", "indices must address items")), GltfReorderAccessorsInverseOperation::Reorder { order } if order.is_empty() || order.len() != after.document.accessors.len() || order.iter().collect::<std::collections::BTreeSet<_>>().len() != order.len() || order.iter().any(|index| *index >= after.document.accessors.len()) => return Err(reject("gltf.mutation.invalid-permutation", "document/accessors", "order must be a non-empty permutation")), _ => {} } let mut next = after.clone(); match operation { GltfReorderAccessorsInverseOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Accessors, &Change::Insert(*position))?; next.document.accessors.insert(*position, item.clone());  }, GltfReorderAccessorsInverseOperation::Delete { index, .. } => { accessors_op(&mut next, GltfTopLevelFamily::Accessors, *index, None, None)?;  }, GltfReorderAccessorsInverseOperation::Move { index, position } => { accessors_op(&mut next, GltfTopLevelFamily::Accessors, *index, Some(*position), None)?;  }, GltfReorderAccessorsInverseOperation::Reorder { order } => { accessors_op(&mut next, GltfTopLevelFamily::Accessors, order[0], None, Some(order))?;  } } Ok(next) }
pub fn encode(inverse: &GltfReorderAccessorsInverse) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(inverse).map_err(|error| reject("gltf.mutation.encode-failed", "inverse", error.to_string())) }
pub fn derive(payload: &GltfReorderAccessorsPayload, base: &GltfSnapshot) -> Result<GltfReorderAccessorsInverse, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfReorderAccessorsInverse { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
